import type { Metadata, Viewport } from "next";
import { Sora } from "next/font/google";
import { GeistSans } from "geist/font/sans";
import { GeistMono } from "geist/font/mono";
import { ClerkProvider } from "@clerk/nextjs";
import { features } from "@/lib/config";
import { SITE_URL } from "@/lib/site";
import { SiteAnalytics } from "@/components/kairo/SiteAnalytics";
import { ToastProvider } from "@/components/ui/Toast";
import "./globals.css";

const sora = Sora({
  variable: "--font-sora",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  display: "swap",
});

const title = "Solaspace — AI goal planner that maps every step";
const description =
  "Tell Solaspace your goal. It maps every step with the exact videos and guides you need, then builds a focused plan for today from your time and energy.";

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title,
  description,
  applicationName: "Solaspace",
  appleWebApp: { capable: true, title: "Solaspace", statusBarStyle: "black-translucent" },
  openGraph: { title, description, url: SITE_URL, siteName: "Solaspace", type: "website" },
  twitter: { card: "summary_large_image", title, description },
};

export const viewport: Viewport = {
  themeColor: "#0a0b0d",
  width: "device-width",
  initialScale: 1,
  viewportFit: "cover",
};

export default function RootLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <html
      lang="en"
      suppressHydrationWarning
      className={`${sora.variable} ${GeistSans.variable} ${GeistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full">
        {/* Set the theme before paint so there's no flash. Dark is the default;
            light is opt-in (kairo.theme.v1). */}
        <script
          dangerouslySetInnerHTML={{
            __html:
              "(function(){try{var t=localStorage.getItem('kairo.theme.v1');var d=(t==='light')?'light':'dark';document.documentElement.setAttribute('data-theme',d);var m=document.querySelector('meta[name=\"theme-color\"]');if(m)m.setAttribute('content',d==='light'?'#f6f6f3':'#0a0b0d');}catch(e){document.documentElement.setAttribute('data-theme','dark');}})();",
          }}
        />
        {/* ClerkProvider only when Clerk is configured; demo mode runs bare. */}
        {features.clerk ? (
          <ClerkProvider><ToastProvider>{children}</ToastProvider></ClerkProvider>
        ) : (
          <ToastProvider>{children}</ToastProvider>
        )}
        <SiteAnalytics />
      </body>
    </html>
  );
}
